Node* closest = nullptr;
float min_distance = std::numeric_limits<float>::max();

for (const auto& node : graph.getNodes()) {
    // Check if node is connected to any non-footway road
    bool has_non_footway = false;
    for (const auto& edge : graph.getEdges(node)) {
        if (edge.road_type != RoadType::FOOTWAY) {
            has_non_footway = true;
            break;
        }
    }

    if (!has_non_footway) {
        continue; // Skip nodes that are only accessible via footways
    }

    // Calculate Euclidean distance
    float dx = node.x - x;
    float dy = node.y - y;
    float distance = std::sqrt(dx * dx + dy * dy);

    if (distance < min_distance) {
        min_distance = distance;
        closest = const_cast<Node*>(&node);
    }
}

return closest;
// END_CODE

